/* Local training episode: outcomes never depend on animation timing. */
(() => {
  'use strict';
  const KEY='ochakovo-bottling-episode-v5';
  const steps=['Путь партии','Образец','Наблюдение','Отклонение','Реакция','Сообщение','Команда','Результат'];
  const nodes=[
    {id:'supply',name:'Подача тары',short:'Тара',x:11,stage:0,text:'Пустые ПЭТ-бутылки приходят от выдувного участка в закрытую зону подготовки. Тара и напиток поступают разными путями.',result:'Подготовленная пустая тара'},
    {id:'filler',name:'Наполнение',short:'Розлив',x:32,stage:1,text:'Подготовленный газированный напиток поступает по закрытой коммуникации. Наполнитель дозирует его в подготовленную тару.',result:'Наполненная бутылка'},
    {id:'capper',name:'Укупоривание',short:'Крышка',x:54,stage:2,text:'Крышки приходят по отдельному каналу. Узел устанавливает их на горлышко; контроль следит за внешними признаками укупоривания.',result:'Закрытая наполненная бутылка'},
    {id:'coder',name:'Этикетка и код',short:'Маркировка',x:72,stage:3,text:'Бутылка получает этикетку и код партии. Проверяют положение и читаемость; содержание кода сверяют с заданием на выпуск.',result:'Продукция с этикеткой и кодом'},
    {id:'control',name:'Контроль',short:'Контроль',x:83,stage:3,text:'Система сопоставляет признаки с заданием. Событие сохраняется в журнале, отмеченная бутылка автоматически отводится на проверку.',result:'Решение по результатам контроля'},
    {id:'packer',name:'Упаковка',short:'Упаковка',x:95,stage:4,text:'Допущенные бутылки собираются в группы и упаковываются в термоусадочную плёнку. Оператор наблюдает за выходом и накоплением перед узлом.',result:'Групповая упаковка'}
  ];
  const checks=[
    {id:'level',name:'Видимый уровень',answer:'visual',why:'По изображению видно явное отличие уровня. Точное количество подтверждают измерением.'},
    {id:'cap',name:'Положение крышки',answer:'visual',why:'Перекос можно увидеть. Ровное положение ещё не подтверждает герметичность.'},
    {id:'code',name:'Этикетка и код',answer:'visual',why:'Положение и читаемость видны. Содержание кода сверяют с заданием.'},
    {id:'seal',name:'Герметичность',answer:'measure',why:'Герметичность подтверждают предусмотренной проверкой, а не внешним видом крышки.'},
    {id:'drink',name:'Газ и состав напитка',answer:'measure',why:'Содержание растворённого газа и другие показатели напитка требуют измерений и участия специалистов.'}
  ];
  const frames=[
    {title:'Исходный кадр',source:'До события',bad:false,description:'Крышка расположена ровно. Видимый уровень сопоставим с образцом. Код У-17 читается.'},
    {title:'Событие А',source:'После укупоривания',bad:true,description:'Крышка наклонена относительно горлышка. Видимый уровень сопоставим с образцом. Код У-17 читается.'},
    {title:'Событие Б',source:'Следующий кадр контроля',bad:true,description:'На другой бутылке снова виден перекос крышки. Уровень сопоставим с образцом. Код У-17 читается.'}
  ];
  const messages=[
    {id:'to',label:'Кому',options:['Инженерной команде','Коллеге без указания команды']},
    {id:'where',label:'Где',options:['На выходе укупоривания партии У-17','Где-то на линии']},
    {id:'what',label:'Что наблюдаем',options:['Повторяется перекос крышек. Кадры приложены','Сломалась укупорочная головка','Вся партия бракованная']},
    {id:'state',label:'Что уже сделано',options:['Наставник остановил участок. Продукция ожидает проверки','Проблема уже решена']},
    {id:'ask',label:'Что требуется',options:['Проверить подачу и установку крышек','Сразу разрешить выпуск всей партии']}
  ];
  const icons={play:'<path d="m9 5 10 7-10 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',zoom:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M7 10h6m-3-3v6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',check:'<path d="m5 12 4 4L19 6"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5ZM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',flag:'<path d="M5 21V3m0 1h13l-3 4 3 4H5"/>',file:'<path d="M5 3h10l4 4v14H5ZM9 11h6m-6 4h6"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 3M4 16l2 3a8 8 0 0 0 13-2"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>'};
  const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||''}</svg>`;
  function bottle({stage=3,bad=false,sample=false}={}){
    return `<svg class="bl-bottle" viewBox="0 0 100 240" aria-hidden="true"><path d="M37 28v29C37 69 20 72 20 94v122q0 15 15 15h30q15 0 15-15V94c0-22-17-25-17-37V28Z" fill="#f7faf8" fill-opacity=".78" stroke="#889a96" stroke-width="1.6"/><g class="bl-liquid" style="${stage<1?'opacity:0':''}"><path d="M25 91h50v124q0 10-11 10H36q-11 0-11-10Z" fill="#593729" fill-opacity=".9"/><path d="M25 91q25-3 50 0" fill="none" stroke="#a37b51" stroke-width="2"/></g><path d="M30 99v103" fill="none" stroke="white" stroke-opacity=".75" stroke-width="3" stroke-linecap="round"/><path d="M24 199q26 8 52 0m-52 10q26 8 52 0M25 112h50" fill="none" stroke="#eef5ef" stroke-opacity=".4"/><g class="bl-cap" transform="rotate(${bad?-13:0} 50 28)" style="${stage<2?'opacity:0':''}"><rect x="33" y="14" width="34" height="18" rx="3" fill="#d50032"/><path d="M38 17v11m6-11v11m6-11v11m6-11v11m6-11v11" stroke="#fff" stroke-opacity=".45"/><path d="M35 33h30" stroke="#a50029" stroke-width="3"/></g><g class="bl-label" style="${stage<3?'opacity:0':''}"><rect x="21" y="128" width="58" height="50" rx="2" fill="#d50032"/><path d="M27 136h46m-46 34h46" stroke="#fff" stroke-opacity=".5"/><text x="50" y="156" text-anchor="middle" fill="white" font-size="12" font-weight="800">КОЛА</text><text x="50" y="120" text-anchor="middle" fill="#282724" font-size="12">У-17</text></g>${sample?'<path d="M13 91h74" stroke="#26704d" stroke-width="1.4" stroke-dasharray="3 3"/>':''}</svg>`;
  }
  Object.assign(window.OchakovoShift.roles.line,{lead:'Сопроводи одну партию: наблюдай за потоком, сопоставляй признаки с контролем и передавай понятную информацию команде.',day:'Оператор следит за подачей тары и крышек, передачей между машинами, продукцией и сообщениями оборудования. Он сопоставляет наблюдения с измерениями и вовремя подключает коллег. Стажёр действует рядом с наставником.',tools:'Задание на выпуск, панель оборудования, журнал контроля и результаты проверок.',learned:'Проследил путь партии, заметил повторяющийся перекос крышек и передал сообщение. Различил проверку оборудования и решение по продукции.'});
  const mission=window.GameMissions.list.find(x=>x.id==='line');if(mission)mission.minutes=9;
  window.OchakovoShift.register('line',a=>{
    const {button:b,esc}=a;
    const fresh=()=>({version:5,phase:0,path:[],node:'supply',classified:{},check:'level',observed:[],frame:1,seenFrames:[],defect:'',linked:'',recorded:false,repeat:false,stopped:false,sent:false,message:{},team:[],teamTab:'engineering',matched:false,trial:false,trialStarted:false,trialCompared:false,trialResults:false,completed:false,low:false,still:0});
    let s=fresh(),resume=false,storageOK=true,paused=false,zoom=false,lens='all',sound=false,audio=null,audioGain=null,oscillator=null,inView=true,disposed=false,journal=false,motionElapsed=0;
    try{const stored=JSON.parse(localStorage.getItem(KEY)||'null');if(stored?.version===5&&Number.isInteger(stored.phase)&&stored.phase>=0&&stored.phase<8&&Array.isArray(stored.path)&&Array.isArray(stored.observed)&&Array.isArray(stored.team)&&Array.isArray(stored.seenFrames)&&stored.classified&&stored.message){s={...fresh(),...stored};resume=s.phase>0||s.path.length>0;}}catch{storageOK=false;}
    s.path=[...new Set(s.path.filter(id=>nodes.some(n=>n.id===id)))];
    s.observed=[...new Set(s.observed.filter(id=>['supply','capper','packer'].includes(id)))];
    s.team=[...new Set(s.team.filter(id=>['engineering','lab','technology'].includes(id)))];
    s.seenFrames=[...new Set(s.seenFrames.filter(i=>Number.isInteger(i)&&i>=0&&i<3))];
    if(!['engineering','lab','technology'].includes(s.teamTab))s.teamTab='engineering';
    if(!Number.isInteger(s.frame)||!frames[s.frame])s.frame=1;
    s.classified=Object.fromEntries(checks.filter(c=>['visual','measure'].includes(s.classified[c.id])).map(c=>[c.id,s.classified[c.id]]));
    s.message=Object.fromEntries(messages.filter(m=>s.message[m.id]!==''&&Number.isInteger(Number(s.message[m.id]))&&m.options[Number(s.message[m.id])]).map(m=>[m.id,String(s.message[m.id])]));
    const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storageOK=false;}};
    const machineState=()=>s.trial?'Работает после проверки':s.trialStarted?'Проверочный запуск':s.stopped?'Остановлено для проверки':'Работает';
    const hasEvent=()=>s.phase>=3||s.stopped;
    const low=()=>s.low||window.matchMedia('(prefers-reduced-motion: reduce)').matches||window.GameMotion?.enabled()===false;
    const moving=()=>!low()&&!paused&&(!s.stopped||s.trialStarted||s.trial)&&!document.hidden&&inView;
    function status(){return `<div class="bl-status"><span class="bl-status-machine ${s.stopped&&!s.trial&&!s.trialStarted?'is-hold':''}"><i></i>Оборудование: <strong>${machineState()}</strong></span><span>${low()?'Покадровый просмотр':paused?'Кадр для осмотра':'Анимация процесса'}</span></div>`;}
    function panorama(){const n=nodes.find(n=>n.id===s.node)||nodes[0];return `<div class="bl-visual ${zoom?'is-close':''} ${moving()?'is-moving':''} ${hasEvent()?'has-event':''}" data-node="${n.id}" style="--focus:${n.x}%"><div class="bl-world"><img class="bl-panorama" src="assets/bottling-panorama-v1.png" alt="Учебная панорама: подача ПЭТ-тары, наполнитель и укупоривание за ограждениями, маркировка и упаковщик" width="1672" height="941" fetchpriority="high"><div class="bl-flow" aria-hidden="true">${Array.from({length:8},(_,i)=>`<div class="bl-traveller" style="--delay:-${i*4}s;--pos:${(i*13+s.still*7)%99}%">${bottle({stage:((i*13+s.still*7)%99)<23?0:((i*13+s.still*7)%99)<49?1:((i*13+s.still*7)%99)<66?2:3,bad:hasEvent()&&i===5&&!s.trial&&!s.trialStarted})}</div>`).join('')}</div><div class="bl-node-marker" style="left:${n.x}%"><span>${icon('eye')}</span></div>${hasEvent()?`<div class="bl-divert ${s.trial?'is-resolved':''}"><span>${icon('flag')} ${(s.trial||s.team.includes('technology'))?'Не допущена':s.stopped?'Ожидает решения':'Требует проверки'}</span><div>${bottle({bad:true})}${bottle({bad:true})}</div></div>`:''}</div><span class="bl-scene-caption">У-17 · учебная партия</span>${zoom?`<span class="bl-close-caption" id="bl-close-heading" role="heading" aria-level="3" tabindex="-1">${esc(n.name)} · крупный план</span>`:''}</div>`;}
    function toolbar(){return `<div class="bl-toolbar"><div class="bl-view-controls">${b('view',icon(zoom?'back':'zoom')+(zoom?'Общий вид':'Крупный план'),'','bl-tool',`aria-pressed="${zoom}"`)}${low()?`${b('still-back',icon('back'),'','bl-tool bl-icon','aria-label="Предыдущий кадр"')}${b('still-next',icon('arrow'),'','bl-tool bl-icon','aria-label="Следующий кадр"')}`:b('pause',icon(paused?'play':'pause')+(paused?'Продолжить просмотр':'Пауза просмотра'),'','bl-tool',`aria-pressed="${paused}"`)}</div><div class="bl-options">${b('low',icon('eye')+'Меньше движения','','bl-tool',`aria-pressed="${s.low}"`)}${b('sound',icon('sound'),'','bl-tool bl-icon',`aria-label="${sound?'Выключить':'Включить'} звук" aria-pressed="${sound}"`)}</div></div>${paused&&!low()?'<p class="bl-pause-note">Пауза только в изображении. '+(s.stopped&&!s.trial&&!s.trialStarted?'Оборудование остановлено по решению наставника.':'Оборудование в учебной ситуации продолжает работать.')+'</p>':''}`;}
    function route(){return `<div class="bl-route" role="group" aria-label="Участки линии">${nodes.map((n,i)=>b('node',`<span>${i+1}</span><strong>${n.short}</strong>${s.path.includes(n.id)?icon('check'):''}`,n.id,'bl-route-node '+(s.node===n.id?'is-active':''),`aria-pressed="${s.node===n.id}"`)).join('')}</div>`;}
    function journalPanel(){return `<section class="bl-journal-drawer" aria-label="Сохранённые наблюдения"><h4>Журнал партии У-17</h4>${s.observed.length?`<ul>${s.observed.map(id=>`<li>${icon('check')}<span><strong>${esc(nodes.find(n=>n.id===id).name)}</strong><small>Исходное состояние: без видимого затора или активного предупреждения</small></span></li>`).join('')}</ul>`:'<p>Пока нет сохранённых наблюдений. На шаге наблюдения сохрани три исходных состояния.</p>'}${hasEvent()?`<div class="bl-journal-captures">${frames.map(f=>`<div>${bottle({bad:f.bad})}<strong>${f.title}</strong><p>${f.description}</p></div>`).join('')}</div>`:''}</section>`;}
    const coach=text=>`<div class="bl-coach"><span class="bl-coach-mark">${icon('team')}</span><div><strong>Наставник</strong><p>${text}</p></div></div>`;
    const task=(title,text)=>`<div class="bl-task-title"><h3 tabindex="-1" id="bl-task-title">${title}</h3><p>${text}</p></div>`;
    const cta=(label='Продолжить',hint='')=>`<div class="bl-next"><span>${hint}</span>${b('next',label+icon('arrow'),'','primary')}</div>`;
    const description=f=>`<details class="bl-description"><summary>Текстовое описание кадра</summary><p>${esc(f.description)}</p></details>`;
    function specimen(bad=false){return `<div class="bl-specimen lens-${lens}"><div class="bl-specimen-object">${bottle({bad,sample:lens==='level'})}</div><span class="bl-object-label">${bad?'Кадр контроля':'Учебный образец'}</span>${lens==='cap'?'<span class="bl-measure-label">Положение относительно горлышка</span>':lens==='level'?'<span class="bl-measure-label">Видимый уровень · учебный образец</span>':lens==='code'?'<span class="bl-code-enlarged">У-17 <small>Ожидаемый учебный код</small></span>':''}</div>`;}
    function lenses(action='lens'){return `<div class="bl-lenses" role="group" aria-label="Область осмотра">${[['all','Вся бутылка'],['level','Уровень'],['cap','Крышка'],['code','Код']].map(([v,t])=>b(action,t,v,'bl-tab '+(lens===v?'is-active':''),`aria-pressed="${lens===v}"`)).join('')}</div>`;}
    function messageText(){const parts=messages.map(m=>s.message[m.id]!==undefined&&s.message[m.id]!==''?m.options[Number(s.message[m.id])]:null).filter(Boolean);return parts.length?esc(parts.join('. ')+'.'):'Выбери блоки. Здесь появится твоё сообщение коллеге.';}

    function trialPanel(){
      if(s.trial)return '<div class="bl-trial-result"><strong>'+icon('check')+'Проверочный выпуск подтверждён</strong><p>Новые кадры сопоставлены с образцом, результаты проверок просмотрены. Наставник продолжил работу. Ранее выделенный сегмент остаётся недопущенным.</p></div>';
      if(!s.trialStarted)return b('trial',icon('play')+'Посмотреть проверочный запуск','','primary');
      return `<section class="bl-trial-inspection" aria-label="Проверочный выпуск"><h4>Проверочный кадр после устранения сбоя</h4><p>Наставник выполняет проверочный запуск. Сравни новую бутылку с образцом и открой результаты контроля.</p><div class="bl-compare"><div>${bottle({sample:true})}<span>Образец</span></div><div>${specimen(false).replace('Учебный образец','Проверочный кадр')}</div></div>${lenses('trial-lens')}<p class="bl-trial-check">${s.trialCompared?'Положение крышки сопоставлено с образцом.':'Открой область «Крышка» и сравни положение относительно горлышка.'}</p>${s.trialResults?'<div class="bl-new-results"><h4>Результаты проверочного выпуска</h4><ul><li>Положение крышек соответствует образцу.</li><li>Повторение в проверочном выпуске не обнаружено.</li><li>Отобранные новые образцы прошли предусмотренные проверки.</li></ul><p>Эти результаты относятся к новому проверочному выпуску. Статус ранее выделенной продукции сохраняется.</p></div>':b('trial-results',icon('file')+'Открыть новые результаты контроля','','secondary')}${b('trial-confirm','Узнать решение наставника'+icon('arrow'),'','primary')}</section>`;
    }

    function stepBody(){
      if(s.phase===0){const n=nodes.find(n=>n.id===s.node)||nodes[0];return `${task('От пустой тары до упаковки','Выбирай участки на схеме и проследи, что каждый передаёт следующему.')}${route()}<div class="bl-node-detail"><div><h4>${esc(n.name)}</h4><p>${esc(n.text)}</p></div><div class="bl-node-product">${bottle({stage:n.stage})}<span>${esc(n.result)}</span></div></div>${coach('Сегодня ты рядом со мной на линии. Тара, напиток и крышки поступают разными путями. Начни с подачи тары и проследи всю цепочку.')}${cta('К образцу',`Открыто ${s.path.length} из ${nodes.length} участков`)}`;}
      if(s.phase===1){const item=checks.find(c=>c.id===s.check)||checks[0];return `${task('Что расскажет внешний вид?','Сверь продукцию с образцом. Для каждого признака выбери источник информации.')}<div class="bl-inspection"><div>${specimen()}${lenses()}</div><div class="bl-classify"><div class="bl-check-list" role="group" aria-label="Признаки продукции">${checks.map(c=>b('check-item',`${s.classified[c.id]===c.answer?icon('check'):icon('eye')}<span>${c.name}</span>`,c.id,'bl-check-item '+(s.check===c.id?'is-active':''),`aria-pressed="${s.check===c.id}"`)).join('')}</div><h4>${esc(item.name)}</h4><div class="bl-classify-actions">${b('classify','По изображению','visual','bl-choice',`aria-pressed="${s.classified[item.id]==='visual'}"`)}${b('classify','Измерение / специалист','measure','bl-choice',`aria-pressed="${s.classified[item.id]==='measure'}"`)}</div><p class="bl-explanation">${s.classified[item.id]?esc(item.why):'Выбери, что достаточно для проверки этого признака.'}</p></div></div>${coach('Положение крышки видно. Герметичность, точное количество и показатели напитка подтверждают отдельными проверками. Читаемый код нужно сверить с заданием.')}${cta('Наблюдать за партией',`Разобрано ${checks.filter(c=>s.classified[c.id]===c.answer).length} из ${checks.length} признаков`)}`;}
      if(s.phase===2){const points=[['supply','Подача','Тара проходит подготовку, видимого затора нет. Крышки поступают по отдельному каналу.'],['capper','После укупоривания','Крышки на вид ровные. Контроль не сообщает об активном отклонении.'],['packer','Перед упаковкой','Продукция уходит в упаковщик. Очередь перед узлом не растёт.']];const p=points.find(p=>p[0]===s.node)||points[0];return `${task('Наблюдай за всем потоком','Сохрани исходное наблюдение в каждой из трёх точек. Оно пригодится для сравнения.')}<div class="bl-observation-points">${points.map(([id,name])=>b('observe-point',`${s.observed.includes(id)?icon('check'):icon('eye')}<span>${name}</span>`,id,'bl-choice '+(s.node===id?'is-active':''),`aria-pressed="${s.node===id}"`)).join('')}</div><div class="bl-observation"><div><h4>${p[1]}</h4><p>${p[2]}</p></div>${b('snapshot',icon('file')+(s.observed.includes(p[0])?'Наблюдение сохранено':'Сохранить наблюдение'),p[0],'secondary',s.observed.includes(p[0])?'disabled':'')}</div><div class="bl-control-strip"><span><i></i> Активных предупреждений нет</span><span>Осмотрено ${s.observed.length} / 3 точек</span></div>${coach('Сопоставляй сообщения панели с самим процессом. Проверь подачу, выход из укупоривания и подход к упаковке. Скорость здесь не важна.')}${cta('Продолжить наблюдение','Кадры сохраняются в журнале')}`;}
      if(s.phase===3){const f=frames[s.frame];return `${task('Что изменилось после укупоривания?','Сравни кадры, отметь признак и свяжи его с участком.')}<div class="bl-alert">${icon('flag')}<div><strong>Контроль после укупоривания</strong><span>Продукция автоматически отведена. События доступны без ограничения времени.</span></div></div><div class="bl-journal"><div class="bl-frame-list" role="group" aria-label="Журнал контроля">${frames.map((f,i)=>b('frame',`${bottle({bad:f.bad})}<span><strong>${f.title}</strong><small>${f.source}</small></span>${s.seenFrames.includes(i)?icon('check'):''}`,i,'bl-frame '+(s.frame===i?'is-active':''),`aria-pressed="${s.frame===i}"`)).join('')}</div><div class="bl-frame-detail"><div class="bl-compare"><div>${bottle({sample:true})}<span>Образец</span></div><div>${specimen(f.bad)}</div></div>${lenses('defect-lens')}${description(f)}</div></div><div class="bl-link"><label for="bl-link-node">С каким участком связано наблюдение?</label><select id="bl-link-node" data-input="link"><option value="">Выбери участок</option>${nodes.map(n=>`<option value="${n.id}" ${s.linked===n.id?'selected':''}>${n.name}</option>`).join('')}</select></div>${s.defect==='cap'&&s.linked==='capper'?'<p class="bl-cause">Перекос крышки → укупоривание → проверить подачу и установку. Причина ещё не установлена.</p>':''}${coach('Открой исходный кадр и оба события. На разных бутылках повторяется один признак. Уровень и код помогают описать картину, но не отменяют проблему крышки.')}${cta('К действиям стажёра','Отметь область отклонения и найди участок')}`;}
      if(s.phase===4){return `${task('Зафиксируй и позови наставника','Твоя роль — передать наблюдение. Остановкой и проверкой оборудования руководит наставник.')}<div class="bl-action-record"><div><span>Участок</span><strong>Укупоривание · У-17</strong></div><div><span>Наблюдение</span><strong>Повторяющийся перекос крышек</strong></div><div><span>Приложения</span><strong>Исходный кадр + события А и Б</strong></div></div><div class="bl-trainee-actions">${b('record',`${s.recorded?icon('check'):icon('file')} Зафиксировать наблюдение`,'','bl-choice',`aria-pressed="${s.recorded}"`)}${b('repeat',`${s.repeat?icon('check'):icon('eye')} Отметить повторяемость`,'','bl-choice',`aria-pressed="${s.repeat}"`)}</div>${s.stopped?`<div class="bl-production-stop"><strong>${icon('pause')} Производственная остановка участка</strong><p>Наставник согласованно прекратил подачу и остановил затронутое оборудование. По журналу выделена часть выпуска для проверки.</p><div class="bl-segment"><span>У-17 · выделенный сегмент</span><strong>Ожидает решения · отгрузка запрещена</strong></div></div>`:b('mentor',icon('team')+'Позвать наставника','','primary')}<details class="bl-wrong-actions"><summary>Проверить своё решение</summary><div>${b('wrong-single','Считать событие единичным','','bl-tool')}${b('wrong-pass','Разрешить выпуск по уровню и коду','','bl-tool')}</div></details>${coach(s.stopped?'Вижу повторение. Участок остановлен. Автоматически отведённые бутылки и выделенная по журналу продукция проверяются отдельно от допущенной.':'Запиши признак и повторение. Я приму производственное решение и подключу коллег.')}${cta('Составить сообщение','Наставник определяет границы проверки вместе со специалистами')}`;}
      if(s.phase===5){return `${task('Передай факты команде','Собери короткое сообщение из смысловых блоков. Причину ещё предстоит установить.')}<div class="bl-message-layout"><div class="bl-message-fields">${messages.map(m=>`<label for="bl-msg-${m.id}"><span>${m.label}</span><select id="bl-msg-${m.id}" data-input="message-${m.id}" ${s.sent?'disabled':''}><option value="">Выбери смысловой блок</option>${m.options.map((t,i)=>`<option value="${i}" ${String(s.message[m.id])===String(i)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`).join('')}</div><div class="bl-message-preview"><span>${icon('file')} Сообщение внутри игры</span><p id="bl-message-text">${messageText()}</p><div class="bl-attachment">${icon('file')} У-17 · кадры контроля</div>${s.sent?'<div class="bl-reply"><strong>Инженерная команда</strong><p>Место и признак понятны. Проверим узел после необходимых мер безопасного доступа.</p></div>':b('send','Передать сообщение'+icon('arrow'),'','primary')}</div></div>${coach('Укажи участок, наблюдаемый признак и текущее состояние. Лаборатория проверит отобранные образцы, технолог сопоставит результаты и решит вопрос по продукции.')}${cta('Узнать результаты',s.sent?'Сообщение передано. Коллеги получили контекст.':'Сообщение можно исправить перед передачей')}`;}
      if(s.phase===6){const teams={engineering:{name:'Инженерная команда',title:'Проверен узел укупоривания',text:'После необходимых мер безопасного доступа команда проверила подачу и установку крышек. В этой учебной ситуации устранён сбой подачи крышек.',quote:'Узел проверен. Нужен проверочный запуск.',result:'Результат относится к оборудованию'},lab:{name:'Лаборатория',title:'Образцы проверены отдельно',text:'У образцов с перекосом герметичность не подтверждена. Проверенные показатели напитка соответствуют заданию. Результат образцов не является автоматическим допуском всего сегмента.',quote:'Показатели напитка в порядке. Это не отменяет проблему укупоривания.',result:'Результат относится к проверенным образцам'},technology:{name:'Технолог',title:'По продукции принято решение',text:'Сопоставлены результаты, сведения линии и границы выделенного выпуска. Выделенный сегмент не допущен к выпуску и передан ответственным за дальнейшее обращение. Его не отправляют потребителю.',quote:'Исправление узла не меняет решение по уже выделенной продукции.',result:'Выделенный сегмент · не допущен'}};const t=teams[s.teamTab];return `${task('У оборудования и продукции разные проверки','Открой результаты трёх коллег. Затем реши, что подтверждает исправление узла.')}<div class="bl-team-tabs" role="group" aria-label="Результаты команды">${Object.entries(teams).map(([id,t])=>b('team',`${s.team.includes(id)?icon('check'):icon('team')}<span>${t.name}</span>`,id,'bl-choice '+(s.teamTab===id?'is-active':''),`aria-pressed="${s.teamTab===id}"`)).join('')}</div><div class="bl-team-result"><h4>${t.title}</h4><p>${t.text}</p><blockquote>«${t.quote}»</blockquote><strong>${icon('file')} ${t.result}</strong></div><div class="bl-match"><h4>«Узел исправлен» подтверждает…</h4><div>${b('match','Готовность оборудования к проверочному запуску','equipment','bl-choice',`aria-pressed="${s.matched}"`)}${b('match','Допуск всей ранее выпущенной продукции','product','bl-choice')}</div></div>${trialPanel()}${coach('Оборудование готовят к продолжению, а ранее выделенную продукцию рассматривают отдельно. Проверки требуют времени: здесь ты видишь их итог после сюжетного перехода.')}${cta('Посмотреть судьбу партии',`Открыто ${s.team.length} из 3 результатов`)}`;}
      return `${task('У каждой части партии есть решение','Проследи оба маршрута. Исправление оборудования не возвращает выделенную продукцию в общий поток.')}<div class="bl-outcomes"><div class="bl-outcome is-approved"><span>${icon('check')} Допущенная часть У-17</span><div class="bl-pack">${bottle()}${bottle()}${bottle()}</div><h4>В групповую упаковку</h4><p>Проверенная продукция проходит маркировку и собирается в упаковки.</p></div><div class="bl-outcome is-held"><span>${icon('flag')} Выделенный сегмент У-17</span><div class="bl-held-bottles">${bottle({bad:true})}${bottle({bad:true})}</div><h4>Не допущен к выпуску</h4><p>Отделён и передан ответственным за дальнейшее обращение. Отгрузка запрещена.</p></div></div><ol class="bl-recap"><li>Наблюдение</li><li>Повторение</li><li>Сообщение</li><li>Проверка</li><li>Решение</li></ol>${coach('Ты проследил работу линии, заметил повторение и передал понятное сообщение. Команда проверила узел и продукцию отдельно. Именно так наблюдение помогает качеству.')}<div class="bl-final-check"><h4>Как завершить учебную схему?</h4>${b('final','Сохранить отдельные решения по частям партии','separate','bl-choice',`aria-pressed="${s.completed}"`)}${b('final','Отметить всю партию как допущенную','all','bl-choice')}</div>${s.completed?`<div class="bl-passport"><strong>${icon('check')} Открытие готово для паспорта</strong><p>Путь партии, журнал контроля, сообщение команде и отдельное решение по продукции.</p>${b('finish','Записать открытие'+icon('arrow'),'','primary')}</div>`:''}<div class="bl-replays">${b('replay-event',icon('refresh')+'Повторить ситуацию','','bl-tool')}${b('restart','Пройти эпизод заново','','bl-tool')}</div>`;
    }
    function render(focus=false){if(s.phase===6&&!s.team.includes(s.teamTab))s.team.push(s.teamTab);const clock=a.root.querySelector('.bl-traveller')?.getAnimations?.().find(t=>t.animationName==='bl-travel');if(clock?.currentTime)motionElapsed+=Number(clock.currentTime)/1000;const title=['Путь одной партии','Сначала — образец','Наблюдение за потоком','Сигнал повторяется','Твоя роль в ситуации','Понятное сообщение','Работа одной команды','Партия под наблюдением'][s.phase];
      const html=`<div class="bl-episode"><header class="bl-heading"><div><h1>${title}</h1><p>Газированный напиток · ПЭТ · партия У-17</p></div><span>Шаг ${s.phase+1} <small>из 8</small></span></header><ol class="bl-progress" aria-label="Этапы эпизода">${steps.map((t,i)=>`<li class="${i===s.phase?'is-current':i<s.phase?'is-done':''}" ${i===s.phase?'aria-current="step"':''}><span>${i+1}</span><span>${t}</span></li>`).join('')}</ol>${status()}${panorama()}${toolbar()}${resume?`<div class="bl-resume"><h3 tabindex="-1">${s.completed?'Ты уже познакомился с партией У-17':'Продолжим твою смену?'}</h3><p>Сохранён шаг ${s.phase+1} из 8: ${steps[s.phase].toLowerCase()}. Наблюдения и черновик сообщения на месте.</p><div>${b('resume','Продолжить с сохранённого шага'+icon('arrow'),'','primary')}${b('restart','Начать эпизод заново','','secondary')}</div></div>`:`<div class="bl-workspace">${stepBody()}</div>`}<p class="bl-model-note">Учебная модель · около 8–10 минут · без таймера. Схема, события и результаты вымышлены; это не регламент предприятия.</p>${!storageOK?'<p class="bl-storage-note">Сохранение в браузере недоступно. Текущая попытка сохранится до ухода с эпизода.</p>':''}</div>`;
      a.draw(html,steps,s.phase,'');
      a.root.querySelectorAll('.bl-traveller').forEach((el,i)=>el.style.setProperty('--delay',`-${(i*4+motionElapsed)%32}s`));
      const tools=a.root.querySelector('.bl-toolbar');
      if(tools)tools.insertAdjacentHTML('afterend',`<div class="bl-subtools"><label for="bl-scene-node">Узел осмотра<select id="bl-scene-node" data-input="scene-node">${nodes.map(n=>`<option value="${n.id}" ${s.node===n.id?'selected':''}>${n.name}</option>`).join('')}</select></label>${b('journal',icon('file')+'Журнал'+(s.observed.length?' · '+(s.observed.length+(hasEvent()?3:0)):''),'','bl-tool',`aria-expanded="${journal}"`)}</div>${journal?journalPanel():''}`);
      a.root.dataset.lineStep=String(s.phase);if(!resume)a.say(['Проследи путь партии: открой каждый участок на схеме.','Внешний вид и измерения отвечают на разные вопросы.','Сохрани три наблюдения. Они помогут увидеть изменение.','Сравни исходный кадр с событиями А и Б. Что повторяется?','Зафиксируй наблюдение и позови наставника.','Передай факты: где, что повторяется и что уже сделано.','У оборудования и продукции отдельные результаты проверки.','У каждой выделенной части партии своё решение.'][s.phase],s.completed?'success':'think');syncMotion();save();if(focus)queueMicrotask(()=>{const heading=a.root.querySelector('.bl-heading h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}});
    }
    const fail=text=>a.feedback(text);
    function ready(){return [()=>s.path.length===nodes.length,()=>checks.every(c=>s.classified[c.id]===c.answer),()=>s.observed.length===3,()=>s.seenFrames.length===3&&s.defect==='cap'&&s.linked==='capper',()=>s.stopped,()=>s.sent,()=>s.trial,()=>s.completed][s.phase]();}
    function next(){if(!ready()){fail(['Открой все шесть участков, чтобы проследить путь партии.','Разбери каждый признак: где достаточно изображения, а где нужны измерения.','Сохрани наблюдение в каждой из трёх точек.','Посмотри исходный кадр и оба события. Отметь крышку и свяжи наблюдение с укупориванием.','Зафиксируй наблюдение, отметь повторение и позови наставника.','Собери и передай сообщение инженерной команде.','Открой все результаты, раздели оборудование и продукцию, затем посмотри проверочный запуск.','Сохрани отдельные решения по частям партии.'][s.phase]);return;}s.phase=Math.min(7,s.phase+1);zoom=false;lens='all';paused=false;if(s.phase===2)s.node='supply';if(s.phase===3){s.node='capper';s.seenFrames=[...new Set([...s.seenFrames,1])];tone();}render(true);}
    function syncMotion(){a.root.querySelector('.bl-visual')?.classList.toggle('is-moving',moving());if(audioGain&&audio)audioGain.gain.setTargetAtTime(sound&&!document.hidden&&inView&&!paused&&(!s.stopped||s.trialStarted||s.trial)?.006:0,audio.currentTime,.12);}
    function startAudio(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;if(!audio){audio=new Audio();oscillator=audio.createOscillator();audioGain=audio.createGain();oscillator.type='triangle';oscillator.frequency.value=78;audioGain.gain.value=0;oscillator.connect(audioGain);audioGain.connect(audio.destination);oscillator.start();}audio.resume().catch(()=>{});syncMotion();}catch{sound=false;fail('Звук недоступен в этом браузере. Все события и реплики есть в тексте.');}}
    function tone(){if(!sound||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=430;g.gain.setValueAtTime(.018,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.22);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.23);}
    function motionChange(){if(!disposed)render();}
    function imageError(e){if(e.target.matches?.('.bl-panorama')){const panel=e.target.closest('.bl-visual');panel.classList.add('image-unavailable');e.target.alt='Панорама недоступна. Подписанная схема и крупные планы остаются доступны.';if(!panel.querySelector('.bl-image-recovery'))panel.insertAdjacentHTML('beforeend','<div class="bl-image-recovery"><p>Иллюстрация не загрузилась. Наблюдения и текущий шаг сохранены.</p>'+b('retry-image','Повторить загрузку иллюстрации','','secondary')+'</div>');}}
    function imageLoaded(e){if(e.target.matches?.('.bl-panorama')){const panel=e.target.closest('.bl-visual');panel?.classList.remove('image-unavailable');panel?.querySelector('.bl-image-recovery')?.remove();}}
    let observer;
    return {
      start(){a.root.addEventListener('error',imageError,true);a.root.addEventListener('load',imageLoaded,true);document.addEventListener('ochakovo:motion',motionChange);document.addEventListener('visibilitychange',syncMotion);if('IntersectionObserver'in window){observer=new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;syncMotion();},{threshold:.05});observer.observe(a.root);}render();},
      done:()=>s.completed,
      input(type,value){if(type==='link'){s.linked=value;save();if(value&&value!=='capper')fail(value==='filler'?'Сравни уровень с образцом. Выбранный признак впервые виден после укупоривания.':'Код читается. Сравни положение крышки с образцом и найди связанный узел.');else if(value==='capper'){render();a.feedback('Наблюдение связано с укупориванием. Конкретную причину ещё предстоит установить.',true);}}
        if(type==='scene-node'&&nodes.some(n=>n.id===value)){s.node=value;render();queueMicrotask(()=>a.root.querySelector('#bl-scene-node')?.focus({preventScroll:true}));}
        if(type.startsWith('message-')&&!s.sent){const id=type.slice(8);if(messages.some(m=>m.id===id)){s.message[id]=value;a.root.querySelector('#bl-message-text').innerHTML=messageText();save();}}},
      act(type,value){
        if(type==='retry-image'){const img=a.root.querySelector('.bl-panorama');if(img)img.src='assets/bottling-panorama-v1.png?retry='+Date.now();return;}
        if(type==='journal'){journal=!journal;render();return;}
        if(type==='resume'){resume=false;render(true);return;}
        if(type==='restart'){s=fresh();resume=false;paused=false;zoom=false;lens='all';render(true);return;}
        if(type==='replay-event'){const lowSetting=s.low;s=fresh();s.low=lowSetting;s.phase=3;s.path=nodes.map(n=>n.id);s.classified=Object.fromEntries(checks.map(c=>[c.id,c.answer]));s.observed=['supply','capper','packer'];s.node='capper';s.seenFrames=[1];paused=false;zoom=false;lens='all';render(true);return;}
        if(type==='view'){zoom=!zoom;render();queueMicrotask(()=>a.root.querySelector(zoom?'#bl-close-heading':'[data-do="view"]')?.focus({preventScroll:true}));return;}if(type==='pause'){paused=!paused;render();return;}if(type==='low'){s.low=!s.low;paused=false;render();return;}
        if(type==='still-next'||type==='still-back'){s.still=(s.still+(type==='still-next'?1:13))%14;render();return;}
        if(type==='sound'){sound=!sound;if(sound)startAudio();render();return;}if(resume)return;if(type==='next'){next();return;}
        if(type==='node'){if(!nodes.some(n=>n.id===value))return;s.node=value;if(s.phase===0&&!s.path.includes(value))s.path.push(value);render();return;}
        if(type==='lens'||type==='defect-lens'){lens=value;if(type==='defect-lens'){s.defect=value;render();if(value!=='cap'&&value!=='all')fail(value==='level'?'Видимый уровень сопоставим с образцом. Сравни крышки на двух событиях.':'Код читается и соответствует учебному заданию. Сравни положение крышек.');}else render();return;}
        if(type==='check-item'){s.check=value;lens=['level','cap','code'].includes(value)?value:'all';render();return;}
        if(type==='classify'){const item=checks.find(c=>c.id===s.check);s.classified[item.id]=value;render();a.feedback(item.why,value===item.answer);return;}
        if(type==='observe-point'){s.node=value;render();return;}if(type==='snapshot'){if(!s.observed.includes(value))s.observed.push(value);render();a.feedback('Исходное наблюдение сохранено в журнале.',true);return;}
        if(type==='frame'){const v=Number(value);if(!frames[v])return;s.frame=v;s.seenFrames=[...new Set([...s.seenFrames,v])];render();return;}
        if(type==='record'||type==='repeat'){s[type==='record'?'recorded':'repeat']=true;render();return;}
        if(type==='mentor'){if(!s.recorded||!s.repeat){fail('Сначала зафиксируй наблюдение и отметь повторяемость: наставнику нужен контекст.');return;}s.stopped=true;render();a.feedback('Наставник остановил участок. Выделенный сегмент ожидает проверки; отправка дальше запрещена.',true);return;}
        if(type==='wrong-single'){fail('На кадрах А и Б разные бутылки с одним признаком. Событие повторяется.');return;}
        if(type==='wrong-pass'){fail('Уровень и код не подтверждают герметичность. Решение по выделенной продукции пока не принято.');return;}
        if(type==='send'){const missing=messages.find(m=>s.message[m.id]===undefined||s.message[m.id]==='');if(missing){fail('Добавь блок «'+missing.label+'». Остальная часть сообщения сохранена.');a.root.querySelector('#bl-msg-'+missing.id)?.focus();return;}const wrong=messages.find(m=>Number(s.message[m.id])!==0);if(wrong){const errors={to:'Укажи инженерную команду, чтобы сообщение было адресным.',where:'Укажи участок укупоривания и партию У-17.',what:Number(s.message.what)===1?'Неисправность конкретной детали ещё не установлена. Передай наблюдаемый перекос и повторение.':'Решения по всей партии нет. Передай факт повторяющегося перекоса крышек.',state:'Участок остановлен; продукция ждёт проверки. Проблема ещё не закрыта.',ask:'Сейчас запрос — проверить подачу и установку крышек. Для допуска нужны результаты проверки.'};fail(errors[wrong.id]);a.root.querySelector('#bl-msg-'+wrong.id)?.focus();return;}s.sent=true;render();a.feedback('Сообщение передано внутри игры. Инженерная команда получила участок, признак и состояние.',true);return;}
        if(type==='team'){if(!['engineering','lab','technology'].includes(value))return;s.teamTab=value;if(!s.team.includes(value))s.team.push(value);render();return;}
        if(type==='match'){if(value==='product'){fail('Исправление узла относится к оборудованию. Ранее выделенная продукция требует отдельного решения.');return;}s.matched=true;render();a.feedback('Исправный узел готовят к проверочному запуску. Статус выделенной продукции сохраняется.',true);return;}
        if(type==='trial'){if(s.team.length<3||!s.matched){fail('Открой три результата и укажи, что подтверждает исправление узла.');return;}s.trialStarted=true;lens='all';render();a.feedback('Наставник выполняет проверочный запуск. Сравни новый кадр с образцом и открой результаты контроля.',true);return;}
        if(type==='trial-lens'){lens=value;if(value==='cap')s.trialCompared=true;render();return;}
        if(type==='trial-results'){s.trialResults=true;render();return;}
        if(type==='trial-confirm'){if(!s.trialCompared||!s.trialResults){fail('Сначала сравни положение крышки с образцом и открой новые результаты контроля.');return;}s.trial=true;render();a.feedback('После проверки наставник продолжил работу. Новые образцы прошли проверки; старый сегмент не допущен.',true);return;}
        if(type==='final'){if(value==='all'){fail('У выделенного сегмента другое решение: он не допущен к выпуску. Сохрани оба маршрута.');return;}s.completed=true;render(true);a.feedback('Эпизод пройден. Запиши открытие в паспорт смены.',true);}
      },
      cleanup(){disposed=true;save();observer?.disconnect();a.root.removeEventListener('error',imageError,true);a.root.removeEventListener('load',imageLoaded,true);document.removeEventListener('ochakovo:motion',motionChange);document.removeEventListener('visibilitychange',syncMotion);if(oscillator)try{oscillator.stop();}catch{}if(audio)audio.close().catch(()=>{});}
    };
  });
})();
